const featureInvoke=invoke;
invoke=async function(name,args){if(name==='windowControl'&&args==='close'||name==='restart')await flushPersonalDrafts();const result=await featureInvoke(name,args);if(result?.items&&state.library?.revision>result.revision)return {...result,...state.library};if(result?.library?.items&&state.library?.revision>result.library.revision)result.library=state.library;return result};
const featureApply=applyPreferences;
applyPreferences=function(){featureApply();document.body.dataset.windowControls=preferences.windowControls||'left';const controls=document.querySelector('.window-controls'),order=preferences.windowControls==='left'?['close','maximize','minimize']:['minimize','maximize','close'];if(controls&&order.some((name,i)=>controls.children[i]?.dataset.windowAction!==name))controls.append(...order.map(name=>controls.querySelector('[data-window-action='+name+']')));const effective=preferences.backgroundMode==='desktop'&&preferences.nativeGlassAvailable===false?'art':preferences.backgroundMode||'art';document.body.dataset.background=effective;document.documentElement.dataset.desktopBackdrop=preferences.interfaceStyle==='liquid'&&['desktop','transparent'].includes(effective)?'true':'false';document.body.style.setProperty('--wallpaper-blur',(preferences.wallpaperBlur||0)+'px');document.body.style.setProperty('--backdrop-tint',String((preferences.backgroundTint||0)/100));if(preferences.backgroundMode==='wallpaper'&&wallpaperAvailable)glassScene.style.setProperty('--wallpaper-image','url("yingji-media://background/wallpaper'+wallpaperStamp+'")');else glassScene.style.removeProperty('--wallpaper-image')};
applyPreferences();invoke('wallpaperInfo').then(info=>{wallpaperAvailable=info.available;applyPreferences()}).catch(()=>{});
async function saveAppearance(patch){preferences=YingjiAppearance.normalize({...preferences,...patch});applyPreferences();try{const saved=await invoke('setPreferences',preferences);windowNeedsRestart=!!saved.requiresRestart;preferences=YingjiAppearance.normalize(saved);applyPreferences();if(state.tab==='settings')renderSettings()}catch(error){toast(error.message)}}
function stars(score,interactive=false,id='workStars'){const value=Math.max(0,Math.min(5,(Number(score)||0)/2));if(!interactive)return`<span class="stars-read" style="--stars-fill:${value/5*100}%" aria-label="我的评分 ${value} / 5">★★★★★</span><span class="stars-number">${value?value+' / 5':'未评分'}</span>`;return`<div class="star-rating" id="${id}" role="group" aria-label="五星评分">${Array.from({length:5},(_,i)=>`<button type="button" data-rate="${(i+1)*2}" data-rating-target="${id}" class="${i+1<=value?'filled':''}" aria-label="${i+1} 星" aria-pressed="${i+1===value}">${svg('star')}</button>`).join('')}<button class="rating-clear" type="button" data-rate="0" data-rating-target="${id}">清除</button><input type="hidden" id="${id==='episodeStars'?'episodeScore':'workPersonalScore'}" value="${score||0}"></div>`}
function ratingPair(work){return`<div class="rating-pair"><span class="personal-rating">${stars(work.personalScore)}</span>${work.sourceScore?`<span class="source-rating">源站 ★ ${Number(work.sourceScore).toFixed(1)} / 10</span>`:''}</div>`}
quickActions=function(work,attr='entry'){const w=savedWork(work),watched=w.status==='watched',watching=w.status==='watching';return`<button class="action-pill ${watched?'done':''}" data-${attr}-action="watched" data-id="${esc(w.id)}" title="点击切换看过／待看；右键移出个人库（需确认删除副本与缓存）" aria-label="${watched?'切换为待看':'标记看过'} ${esc(w.title)}">${svg(watched||watching&&attr==='detail'?'check':watching?'play':'pending')}<span>${watched||watching&&attr==='detail'?'看过':watching?'在看':'待看'}</span></button><button class="action-pill ${w.favorite?'favorite':''}" data-${attr}-action="favorite" data-id="${esc(w.id)}" aria-label="${w.favorite?'取消收藏':'收藏'} ${esc(w.title)}">${svg('heart')}<span>${w.favorite?'已收藏':'收藏'}</span></button>`};
const featureCard=card,featureRow=listRow;
card=function(i){if(i.type!=='record')return featureCard(i);return`<article class="media-card" data-open="${esc(i.id)}" tabindex="0" role="button" aria-label="打开 ${esc(i.title)}"><div class="media-cover">${recordCover(i)}<span class="file-type">${esc(i.category||'未分类')}</span></div><div class="media-caption"><h3>${esc(i.title)}</h3><p>${esc(i.date||'日期待补充')} · ${esc(i.author||i.original||i.source||'个人条目')}</p>${ratingPair(i)}<div class="card-quick-actions">${quickActions(i)}</div></div></article>`};
listRow=function(i){if(i.type!=='record')return featureRow(i);return`<article class="work-row" data-open="${esc(i.id)}" tabindex="0" role="button"><div class="library-poster">${recordCover(i)}</div><div class="work-main"><h3 class="work-title">${esc(i.title)}</h3><p class="work-original">${esc(i.author||i.original||'作者待补充')}</p><div class="work-meta"><span class="type-badge">${esc(i.category||'未分类')}</span><span>${esc(i.date)}</span><span>${statusNames[i.status]||'待看'}</span></div>${ratingPair(i)}</div><div class="catalog-row-actions">${quickActions(i)}<button class="action-pill" data-cache-one="${esc(i.id)}" title="缓存资料">${svg('download')}</button></div></article>`};
catalogCard=function(work){const w=savedWork(work);return`<article class="media-card" data-catalog-open="${esc(w.id)}" role="button" tabindex="0"><div class="media-cover">${recordCover(w)}<span class="file-type">${esc(w.format||w.category)}</span></div><div class="media-caption"><h3>${esc(w.title)}</h3><p>${esc(w.date||'日期待补充')} · ${esc(w.original||w.source)}</p>${ratingPair(w)}<div class="card-quick-actions">${quickActions(w,'catalog')}</div></div></article>`};
const oldFeatureThumbnail=setThumbnail;
setThumbnail=function(node,url){if(!url||!node.isConnected)return;node.innerHTML=`<img src="${esc(url)}" alt="" loading="lazy" decoding="async">`;const image=node.firstElementChild;image.onload=()=>{const cover=node.closest('.masonry-grid .media-cover');if(cover){cover.style.aspectRatio=String(Math.max(.45,Math.min(2.1,image.naturalWidth/image.naturalHeight)));cover.classList.add('ratio-ready')}};image.onerror=async()=>{if(node.dataset.retried==='true'){node.innerHTML='<span class="cover-unavailable">封面暂不可用</span>';return}node.dataset.retried='true';thumbnailCache.delete(node.dataset.thumbnail);try{const result=await invoke('repairThumbnail',node.dataset.thumbnail);if(result)setThumbnail(node,result)}catch{node.innerHTML='<span class="cover-unavailable">封面暂不可用</span>'}};node.style.width='100%';node.style.height='100%';if(image.complete&&image.naturalWidth)image.onload()};
pumpThumbnails=async function(){while(thumbRunning<4&&thumbnailQueue.length){const task=thumbnailQueue.shift();if(!task.node.isConnected)continue;thumbRunning++;(async()=>{try{const url=await invoke('thumbnail',task.id);if(url){thumbnailCache.set(task.id,url);if(thumbnailCache.size>500)thumbnailCache.delete(thumbnailCache.keys().next().value);setThumbnail(task.node,url)}}catch{}finally{thumbRunning--;pumpThumbnails()}})()}};
function densityControl(){return`<div class="inline-density" role="group" aria-label="布局密度">${[['compact','紧凑'],['comfortable','舒适'],['poster','大封面']].map(([key,label])=>`<button data-inline-density="${key}" class="${preferences.density===key?'active':''}">${label}</button>`).join('')}</div>`}
const featureLibrary=renderLibrary,featureResults=renderResults;
renderLibrary=function(){featureLibrary();const toolbar=$('.library-toolbar');toolbar.insertAdjacentHTML('beforeend',`<button class="view-extra ${state.view==='masonry'?'active':''}" data-library-masonry title="瀑布流">${svg('masonry')}</button>${densityControl()}`);$('.library-filters').insertAdjacentHTML('afterend',`<div class="batch-actions" id="batchActions"></div>`);updateBatchBar();decorateLibraryItems()};
renderResults=function(){if(!$('#resultList'))return;if(state.view==='masonry'){const items=filtered();$('#resultCount').textContent=items.length+' 项';$('#resultList').innerHTML=`<div class="masonry-grid library-masonry">${items.slice(0,state.limit).map(card).join('')}</div>${items.length>state.limit?'<button class="load-more" data-action="more">显示更多</button>':''}`;queueThumbnails()}else featureResults();decorateLibraryItems();updateBatchBar()};
function decorateLibraryItems(){document.querySelectorAll('#resultList [data-open]').forEach(article=>{const id=article.dataset.open;if(article.querySelector('.entry-selection'))return;article.classList.toggle('entry-selected',selection.has(id));article.classList.toggle('selection-mode',selectionMode);article.insertAdjacentHTML('afterbegin',`<label class="entry-selection" title="选择条目"><input type="checkbox" data-select-entry="${esc(id)}" ${selection.has(id)?'checked':''} aria-label="选择 ${esc(state.library.items.find(i=>i.id===id)?.title||'条目')}"><span></span></label><button class="entry-delete" data-delete-one="${esc(id)}" aria-label="移除条目">${svg('trash')}</button>`)})}
function updateBatchBar(){const bar=$('#batchActions');if(!bar)return;const ids=new Set(state.library.items.map(i=>i.id));for(const id of selection)if(!ids.has(id))selection.delete(id);bar.innerHTML=`<button class="action-pill ${selectionMode?'done':''}" data-select-mode>${selectionMode?'完成选择':'多选条目'}</button>${selectionMode?`<button class="ghost-link" data-select-all>全选当前筛选（${filtered().length}）</button><button class="ghost-link" data-select-none>取消选择</button><span class="selection-count">已选 ${selection.size} 项</span>`:''}<div class="batch-right"><button class="action-pill" data-cache-batch>${svg('download')}${selection.size?'缓存所选 '+selection.size+' 项':'缓存当前筛选'}</button>${selection.size?`<button class="action-pill danger-quiet" data-delete-selected>${svg('trash')}移除所选</button>`:''}${undoDeletion?'<button class="ghost-link" data-undo-deletion>撤销刚才的移除</button>':''}</div>`}
function chooseDeletion(ids){deleteIds=ids;showSheet(`<div class="detail-kicker">REMOVE FROM LIBRARY</div><h2 class="detail-title">移除 ${ids.length} 个条目？</h2><p class="summary">这些条目及观看记录将从资料库移除。电脑里的图片、视频和数据库原文件会保留。移除后可在资料库工具栏撤销。</p><div class="button-group"><button class="button secondary" data-action="close">取消</button><button class="button danger" data-confirm-entry-delete>移除条目</button></div>`)}
async function cacheBatch(ids){if(!ids.length){toast('当前没有可缓存的条目');return}setTaskStatus('开始缓存 · '+ids.length+' 项',true);try{const result=await invoke('cacheItems',ids);toast(`缓存完成 ${result.done.length} / ${result.total} 项${result.errors.length?'；'+result.errors.length+' 项未完成，可重新缓存':''}`);if(state.tab==='settings')refreshCachePanel()}catch(error){toast(error.message);setTaskStatus('缓存任务未完成')}}

// Discovery: filters, masonry and bounded incremental loading.
const featureCatalog=renderCatalog;
renderCatalog=function(){featureCatalog();const kind=$('#catalogKind');if(![...kind.options].some(o=>o.value==='game'))kind.insertAdjacentHTML('beforeend','<option value="game">游戏 · Bangumi</option>');kind.value=catalogClient.kind;kind.querySelector('option[value=game]').disabled=catalogClient.provider==='tmdb';$('#catalogProvider').onchange=e=>{catalogClient.provider=e.target.value;if(catalogClient.provider==='tmdb'&&catalogClient.kind==='game'){catalogClient.kind='movie';kind.value='movie'}kind.querySelector('option[value=game]').disabled=catalogClient.provider==='tmdb';catalogClient.page=1;loadCatalog()};$('#catalogYear').onchange=e=>{catalogClient.year=e.target.value;if(catalogClient.year==='all'&&catalogClient.quarter!=='all'){catalogClient.quarter='all';$('#catalogQuarter').value='all';$('#catalogQuarter').dispatchEvent(new Event('change',{bubbles:true}))}catalogClient.page=1;loadCatalog()};const toolbar=$('.catalog-toolbar');const dateOption=document.querySelector('#catalogSort option[value=date]');if(dateOption)dateOption.disabled=false;toolbar.insertAdjacentHTML('beforeend',select('catalogQuarter',[['all','全部季度'],['1','冬季 · 1–3 月'],['2','春季 · 4–6 月'],['3','夏季 · 7–9 月'],['4','秋季 · 10–12 月']],catalogClient.quarter)+select('catalogRegion',[['all','全部地区'],['JP','日本'],['CN','中国'],['US','美国'],['KR','韩国'],['GB','英国'],['FR','法国'],['DE','德国'],['CA','加拿大']],catalogClient.region));for(const[id,key]of [['catalogQuarter','quarter'],['catalogRegion','region']])$('#'+id).onchange=e=>{catalogClient[key]=e.target.value;const dateOption=document.querySelector('#catalogSort option[value=date]');if(dateOption)dateOption.disabled=false;if(dateOption?.disabled&&catalogClient.sort==='date'){catalogClient.sort='rank';$('#catalogSort').value='rank';$('#catalogSort').dispatchEvent(new Event('change',{bubbles:true}))}if(key==='quarter'&&catalogClient.quarter!=='all'&&catalogClient.year==='all'){catalogClient.year=String(new Date().getFullYear());$('#catalogYear').value=catalogClient.year;$('#catalogYear').dispatchEvent(new Event('change',{bubbles:true}));return}catalogClient.page=1;loadCatalog()};$('#catalogKind').onchange=e=>{catalogClient.kind=e.target.value;if(catalogClient.kind==='game'){catalogClient.provider='bangumi';$('#catalogProvider').value='bangumi'}catalogClient.page=1;loadCatalog()};$('.catalog-summary .view-switch').insertAdjacentHTML('beforeend',`<button data-catalog-view="masonry" aria-label="瀑布流" class="${catalogClient.view==='masonry'?'active':''}">${svg('masonry')}</button>`);$('.catalog-note').insertAdjacentHTML('beforeend',`<button class="source-web-button" data-open-source-provider>${svg('external')}源站网页</button>`);$('.catalog-summary').insertAdjacentHTML('afterend',`<div class="discovery-layout">${densityControl()}</div>`)};
renderCatalogResults=function(){if(!$('#catalogResults'))return;masonryObserver?.disconnect();const existingGrid=$('#catalogResults .masonry-grid');if(catalogClient.view==='masonry'&&catalogClient.appending&&existingGrid){const ids=new Set([...existingGrid.children].map(c=>c.dataset.catalogOpen));for(const item of catalogClient.items)if(!ids.has(item.id))existingGrid.insertAdjacentHTML('beforeend',catalogCard(item));$('#catalogSummary').innerHTML='<b>'+catalogClient.items.length+' 部作品</b> · 连续浏览';const more=$('[data-masonry-more]');if(more){more.disabled=catalogClient.loading||!catalogClient.hasMore;more.textContent=catalogClient.loading?'正在载入…':catalogClient.hasMore?'继续载入':'已经到底了'}queueThumbnails();if(catalogClient.hasMore&&!catalogClient.loading&&!catalogClient.error){masonryObserver=new IntersectionObserver(entries=>{if(entries.some(e=>e.isIntersecting))loadMoreMasonry()},{root:mainElement,rootMargin:'280px'});masonryObserver.observe($('.masonry-sentinel'))}return;}document.querySelectorAll('[data-catalog-view]').forEach(b=>b.classList.toggle('active',b.dataset.catalogView===catalogClient.view));if(catalogClient.loading&&!catalogClient.appending){$('#catalogResults').innerHTML='<div class="catalog-loading">'+Array.from({length:6},()=>'<div class="catalog-skeleton"></div>').join('')+'</div>';return}if(catalogClient.error&&!catalogClient.items.length){$('#catalogResults').innerHTML=`<div class="catalog-empty"><b>作品资料暂未载入</b>${esc(catalogClient.error)}<br><button class="button secondary" data-catalog-retry>重新读取</button><button class="button secondary" data-route="settings">前往设置</button></div>`;return}$('#catalogSummary').innerHTML=`<b>${catalogClient.items.length} 部作品</b> · 第 ${catalogClient.page} 页 <span class="source-pill">${catalogClient.result?.offline?'离线缓存':catalogClient.result?.cached?'本地缓存':'在线资料'}</span>`;const masonry=catalogClient.view==='masonry';$('#catalogResults').innerHTML=(catalogClient.items.length?`<div class="${masonry?'masonry-grid':catalogClient.view==='grid'?'catalog-grid':'catalog-list'}">${catalogClient.items.map(catalogClient.view==='list'?catalogRow:catalogCard).join('')}</div>`:'<div class="catalog-empty">这个条件下还没有作品，试试其他年份、地区或季度。</div>')+(masonry?`<div class="masonry-sentinel"><button class="button secondary" data-masonry-more ${catalogClient.loading||!catalogClient.hasMore?'disabled':''}>${catalogClient.loading?'正在载入…':catalogClient.hasMore?'继续载入':'已经到底了'}</button>${catalogClient.error?`<p>${esc(catalogClient.error)} · 可点击继续载入重试</p>`:''}</div>`:`<div class="catalog-pagination"><button class="button secondary" data-catalog-page="prev" ${catalogClient.page<=1?'disabled':''}>上一页</button><span>第 ${catalogClient.page} 页</span><button class="button secondary" data-catalog-page="next" ${!catalogClient.hasMore?'disabled':''}>下一页</button></div>`);queueThumbnails();if(masonry&&catalogClient.hasMore&&!catalogClient.loading&&!catalogClient.error){masonryObserver=new IntersectionObserver(entries=>{if(entries.some(e=>e.isIntersecting))loadMoreMasonry()},{root:mainElement,rootMargin:'280px'});masonryObserver.observe($('.masonry-sentinel'))}};
loadCatalog=async function(refresh=false,append=false){window.YingjiSourceOrder?.sync();if(catalogClient.forceRefresh){refresh=true;catalogClient.forceRefresh=false}const requestId=++catalogClient.requestId;catalogClient.loading=true;catalogClient.appending=append;catalogClient.error='';if(!append)catalogClient.items=[];renderCatalogResults();try{const result=await invoke('catalogBrowse',{provider:catalogClient.provider,kind:catalogClient.kind,year:catalogClient.year,quarter:catalogClient.quarter,region:catalogClient.region,sort:catalogClient.sort,query:catalogClient.query,page:catalogClient.page,refresh,sourceOrder:true,format:catalogClient.format});if(requestId!==catalogClient.requestId)return;catalogClient.items=append?[...new Map([...catalogClient.items,...result.items].map(i=>[i.id,i])).values()]:result.items;catalogClient.total=result.total;catalogClient.hasMore=result.hasMore;catalogClient.result=result;for(const item of result.items)catalogClient.byId.set(item.id,item);if(catalogClient.byId.size>1400)for(const id of [...catalogClient.byId.keys()].slice(0,400))if(!state.library.items.some(i=>i.id===id))catalogClient.byId.delete(id);setTaskStatus(result.offline?'网络不可用，显示本地缓存':'作品资料已载入 · '+catalogClient.items.length+' 部');if(result.coverage&&state.tab==='catalog'&&$('.catalog-note>span'))$('.catalog-note>span').textContent=result.coverage}catch(error){if(requestId!==catalogClient.requestId)return;catalogClient.error=error.message;setTaskStatus('作品资料暂未载入')}finally{if(requestId===catalogClient.requestId){catalogClient.loading=false;if(state.tab==='catalog')renderCatalogResults();catalogClient.appending=false}}};
async function loadMoreMasonry(){if(catalogClient.loading||!catalogClient.hasMore)return;catalogClient.page++;await loadCatalog(false,true);if(catalogClient.error){catalogClient.page--;renderCatalogResults()}}

// Dialog geometry: scroll inside the rounded boundary, with a centered vector close button.
const featureShowSheet=showSheet;
function closeIcon(){return`<button class="sheet-close" data-action="close" aria-label="关闭详情">${svg('close')}</button>`}
showSheet=function(html,cls=''){featureShowSheet(html,cls);const sheet=$('#sheet');sheet.querySelector('.sheet-grab')?.remove();sheet.querySelector('.sheet-close')?.remove();const content=document.createElement('div');content.className='sheet-scroll';while(sheet.firstChild)content.append(sheet.firstChild);sheet.append(content);sheet.insertAdjacentHTML('afterbegin',closeIcon())};
const featureClose=closeSheet;
closeSheet=function(){flushPersonalDrafts();featureClose();detailPane='source'};
const featureOpenCatalog=openCatalogWork;
openCatalogWork=async function(id){detailPane='source';await featureOpenCatalog(id)};
const featureOpenItem=openItem;
openItem=async function(id){const item=state.library.items.find(i=>i.id===id);if(item?.type==='record'&&!item.provider){detailPane='personal';catalogDetailState={id,work:item,sourceWork:item,episodes:[],episodeTotal:0};current=item;$('#overlay').hidden=false;renderCatalogDetail();return}return featureOpenItem(id)};
function episodeMarkup(work,episodes){return episodes.length?`<div class="episode-header"><h3>单集记录 <span>${episodes.length} / ${catalogDetailState.episodeTotal||episodes.length} 话</span></h3><span>点击角标：待看 → 看过 → 重点</span></div><div class="episode-grid">${episodes.map(ep=>{const value=episodeValue(work,ep),name={pending:'待看',watched:'看过',important:'重点'}[value.state];return`<div class="episode-card"><button class="ep-cycle ${value.state}" data-episode-cycle="${esc(ep.id)}" aria-label="第 ${ep.number} 集 ${name}，点击切换">${svg(value.state==='watched'?'check':value.state==='important'?'star':'pending')}<span>${name}</span></button><button data-episode-edit="${esc(ep.id)}"><span class="ep-heading">第 ${ep.number} 话</span><span class="ep-name">${esc(ep.title||'标题待补充')}</span>${value.score?`<span class="ep-score">${stars(value.score)}</span>`:''}${value.review?'<span class="ep-score">已有评论</span>':''}</button></div>`}).join('')}</div><div id="episodeEditor"></div>${catalogDetailState.episodeHasMore?'<button class="more-episodes" data-more-episodes>载入更多集数</button>':''}`:''}
renderCatalogDetail=function(){if(!catalogDetailState)return;const work=savedWork(catalogDetailState.work),source=catalogDetailState.sourceWork||catalogDetailState.work;current=work;const sheet=$('#sheet');sheet.className='sheet catalog-detail feature-detail';const draft=reviewDrafts.get(work.id);const review=draft?.review??work.review??'',score=draft?.score??work.personalScore??0;sheet.innerHTML=`<header class="detail-top"><div><p class="detail-kicker">${esc(work.source||'PERSONAL LIBRARY')} / YOUR STORY</p><h2 class="detail-title">${esc(work.title)}</h2><p class="detail-original">${esc(work.original||'')}</p></div>${closeIcon()}</header><div class="detail-nav"><div class="detail-tablist" role="tablist"><button role="tab" data-detail-pane="source" aria-selected="${detailPane==='source'}">${svg('globe')}网页资料</button><button role="tab" data-detail-pane="personal" aria-selected="${detailPane==='personal'}">${svg('heart')}我的空间</button></div><div class="detail-top-actions">${work.provider?`<button class="ghost-link" data-refresh-source="${esc(work.id)}">${svg('refresh')}刷新资料</button><button class="ghost-link" data-cache-one="${esc(work.id)}">${svg('download')}离线缓存</button>`:''}${work.provider||work.sourceUrl?`<button class="ghost-link" data-open-source="${esc(work.id)}">${svg('external')}源站网页</button>`:''}</div></div><div class="detail-scroll" id="detailScroll">${detailPane==='source'?`<div class="catalog-detail-layout"><aside><div class="detail-cover">${recordCover(work)}</div><div class="detail-side-info">${esc(source.source||'手动资料')}<br>${source.rank?'源站排名 '+source.rank+'<br>':''}${esc(source.date||'出品时间待补充')}<br>${source.eps?'全 '+source.eps+' 话':''}</div></aside><div class="detail-main-info"><div class="detail-watch-actions">${quickActions(work,'detail')}<button class="action-pill ${work.status==='watching'?'done':''}" data-detail-action="watching" data-id="${esc(work.id)}">${svg('play')}在看</button><button class="ghost-link" data-action="edit-current">编辑／纠错</button></div>${ratingPair(work)}<div class="detail-facts"><div><label>类目</label><p>${esc(source.category||work.category)}</p></div><div><label>形式</label><p>${esc(source.format||'—')}</p></div><div><label>作者 / 主创</label><p>${esc(source.author||'源站暂未提供')}</p></div></div><div class="detail-description">${esc(source.description||'暂时没有源站简介，可以在编辑资料中补充。')}</div><div class="detail-rate-line"><label>我的评分</label>${stars(score,true)}</div><p class="hint">首次收藏默认整部与已知单集看过，之后可切换为待看或单独调整。个人感受与素材放在“我的空间”。</p>${episodeMarkup(work,catalogDetailState.episodes||[])}</div></div>`:`<section class="personal-space"><div class="personal-space-head"><div><h3>留一点感受，给以后的自己。</h3><p>文字和关联素材保存在本机，源站资料独立保留。</p></div><span id="personalSaveState">自动保存</span></div><div class="detail-rate-line"><label>我的评分</label>${stars(score,true)}${work.sourceScore?`<span class="source-rating">源站 ★ ${Number(work.sourceScore).toFixed(1)} / 10</span>`:''}</div><textarea class="personal-review form-input" id="workReview" aria-label="我的观后感" placeholder="写下看完之后想留下的话…">${esc(review)}</textarea><div class="materials-heading"><h3>我的素材 <small>${work.materialIds?.length||0}</small></h3><button class="action-pill" data-personal-materials>${svg('plus')}添加图片或视频</button></div><div class="material-drop-hint">拖入图片或视频，关联到这个条目 · 原文件保留</div><div class="materials-masonry">${(work.materialIds||[]).map(id=>state.library.items.find(i=>i.id===id)).filter(Boolean).map(material=>`<figure class="material-tile" data-material-id="${esc(material.id)}">${material.type==='video'?`<video src="yingji-media://item/${material.id}" controls preload="none" playsinline></video>`:`<button data-personal-image="${esc(material.id)}" aria-label="查看 ${esc(material.title)}"><img src="yingji-media://item/${material.id}" loading="lazy" alt="${esc(material.title)}"></button>`}<figcaption><span>${esc(material.title)}</span><button data-unlink-material="${esc(material.id)}" aria-label="取消关联">${svg('close')}</button></figcaption></figure>`).join('')}</div></section>`}</div>`;queueThumbnails();sheet.querySelectorAll('.material-tile img,.material-tile video').forEach(media=>{const fit=()=>{const width=media.naturalWidth||media.videoWidth,height=media.naturalHeight||media.videoHeight;if(width&&height)media.style.aspectRatio=String(width/height);scheduleMaterialLayout()};if(media.tagName==='VIDEO')observeVideoPoster(media);media.addEventListener(media.tagName==='VIDEO'?'loadedmetadata':'load',fit);fit()});scheduleMaterialLayout()};
renderEpisodeEditor=function(id){const ep=catalogDetailState?.episodes.find(e=>e.id===id);if(!ep)return;episodeEditing=id;const value=episodeValue(savedWork(catalogDetailState.work),ep);$('#episodeEditor').innerHTML=`<div class="episode-editor"><label>第 ${ep.number} 话 · ${esc(ep.title)}</label><div class="detail-review-row">${stars(value.score,true,'episodeStars')}<button class="action-pill" data-save-episode>保存单集记录</button></div><textarea id="episodeReview" class="form-input" aria-label="单集评论" placeholder="这集有什么想记住的？">${esc(value.review||'')}</textarea></div>`;$('#episodeEditor').scrollIntoView({block:'nearest',behavior:'smooth'})};
persistWatch=async function(id,patch,feedback=true){const scroll=$('#detailScroll')?.scrollTop||0;try{const result=await invoke('watch',{id,...patch});state.library=result;updateNavigation();if(catalogDetailState?.id===id&&!$('#overlay').hidden){renderCatalogDetail();$('#detailScroll').scrollTop=scroll}else if(state.tab==='catalog')renderCatalogResults();else if(state.tab==='library')renderResults();if(feedback)toast('记录已保存，作品资料在后台缓存');return result}catch(error){toast(error.message)}};
function queuePersonalDraft(){if(!current||!$('#workReview'))return;reviewDrafts.set(current.id,{review:$('#workReview').value,score:Number($('#workPersonalScore')?.value||current.personalScore||0),version:Date.now()});if($('#personalSaveState'))$('#personalSaveState').textContent='正在保存…';clearTimeout(reviewTimer);reviewTimer=setTimeout(flushPersonalDrafts,650)}
async function flushPersonalDrafts(){clearTimeout(reviewTimer);for(const[id,draft]of reviewDrafts){reviewWrites=reviewWrites.catch(()=>{}).then(async()=>{try{const result=await invoke('watch',{id,review:draft.review,personalScore:draft.score});state.library=result;if(reviewDrafts.get(id)?.version===draft.version)reviewDrafts.delete(id);if(current?.id===id&&$('#personalSaveState'))$('#personalSaveState').textContent='已保存在本机'}catch(error){toast('观后感尚未保存：'+error.message)}})}await reviewWrites}
async function attachPersonal(files){const id=current?.id;if(!id)return;await flushPersonalDrafts();const result=await invoke(files?'attachDropped':'attachMaterials',files?{id,files:Array.from(files)}:{id});if(!result)return;state.library=result.library;const item=state.library.items.find(i=>i.id===id);if(current?.id===id&&!$('#overlay').hidden&&catalogDetailState?.id===id){current=item;catalogDetailState.work=item;detailPane='personal';renderCatalogDetail()}updateNavigation();toast('已关联 '+result.attachedIds.length+' 项素材，原文件保留')}

// Database requests use their own sequence, never the library entry ID.
openDatabase=async function(item){const request=++dbRequest;current=item;showSheet(`<div class="detail-kicker">DATABASE EXPLORER</div><h2 class="detail-title">${esc(item.filename)}</h2><p class="hint">只读分页浏览 · 原文件保留</p><div id="databaseContent">${databaseProgress()}</div>`,'media-sheet');try{const tables=await invoke('database',{id:item.id});if(current?.id!==item.id||request!==dbRequest)return;dbState={id:item.id,tables,table:tables[0]?.name,offset:0,query:'',limit:50};if(!tables.length){$('#databaseContent').innerHTML='<div class="empty-reader">这个数据库没有数据表</div>';return}$('#databaseContent').innerHTML=`<div class="db-tables">${tables.map(t=>`<button class="chip ${t.name===dbState.table?'active':''}" data-table="${esc(t.name)}">${esc(t.name)}${t.count===null?'':' · '+t.count}</button>`).join('')}</div><div class="search db-search">${svg('search')}<input id="dbSearch" aria-label="搜索当前数据表" placeholder="搜索当前数据表…"></div><div id="dbRows"></div><button class="ghost-link" data-action="reveal">在文件夹中显示</button>${item.sourceUrl?`<button class="ghost-link" data-open-source="${esc(item.id)}">打开源网页</button>`:''}`;let timer;$('#dbSearch').oninput=e=>{const value=e.target.value;clearTimeout(timer);timer=setTimeout(()=>{if(dbState){dbState.query=value;dbState.offset=0;loadRows()}},300)};await loadRows()}catch(error){if(current?.id===item.id&&$('#databaseContent'))$('#databaseContent').innerHTML=`<div class="error-note">${esc(error.message)}</div><button class="action-pill" data-database-retry>重试读取</button>`}};
function databaseProgress(){return'<div class="database-progress" role="status"><div class="job-progress"><i style="width:5%"></i></div><span>准备读取数据库…</span></div>'}
loadRows=async function(){if(!dbState||!$('#dbRows'))return;const query={...dbState},request=++dbRequest;$('#dbRows').innerHTML=databaseProgress();try{const result=await invoke('database',{id:query.id,table:query.table,q:query.query,offset:query.offset,limit:query.limit});if(request!==dbRequest||!dbState||current?.id!==query.id)return;dbState.rows=result.rows;$('#dbRows').innerHTML=`<div class="section-line"><span>${result.total===null?'按需分页':result.total+' 条记录'} · ${result.columns.length} 个字段</span><span>${result.engine==='native'?'本机只读连接':'后台解析'}</span></div><div class="table-scroll"><table><thead><tr>${result.columns.map(c=>`<th>${esc(c)}</th>`).join('')}</tr></thead><tbody>${result.rows.map((row,index)=>`<tr data-row="${index}">${result.columns.map(c=>`<td title="${esc(typeof row[c]==='object'?JSON.stringify(row[c]):row[c])}">${esc(typeof row[c]==='object'?JSON.stringify(row[c]):row[c])}</td>`).join('')}</tr>`).join('')}</tbody></table>${!result.rows.length?'<p class="hint">没有匹配的记录</p>':''}</div><div class="table-pager"><button data-action="db-prev" ${query.offset===0?'disabled':''}>上一页</button><span>${result.rows.length?query.offset+1:0}–${query.offset+result.rows.length}${result.total===null?'':' / '+result.total}</span><button data-action="db-next" ${result.hasMore?'':'disabled'}>下一页</button></div>`}catch(error){if(request===dbRequest&&$('#dbRows'))$('#dbRows').innerHTML=`<div class="error-note">${esc(error.message)}</div><button class="action-pill" data-database-retry>重试读取</button>`}};

// Appearance and cache management live in settings; layout density is also available on each library page.
const featureSettings=renderSettings;
renderSettings=function(){featureSettings();if(state.tab!=='settings')return;const panel=document.createElement('section');panel.className='panel desktop-appearance';panel.innerHTML=`<div class="settings-panel-heading"><h3>窗口与背景</h3><span>随你的桌面，换一种气氛。</span></div><div class="background-settings-grid"><div><label class="form-label">背景方式</label>${select('backgroundMode',[['art','映迹流光'],['wallpaper','我的背景图片'],['desktop','桌面实时磨砂 · Windows 11']],preferences.backgroundMode)}<p class="hint">桌面模式使用系统实时磨砂，窗口可拖动和缩放。流光与背景图片支持 Demo 式折射与磨砂调节。</p></div><div><label class="form-label">窗口按钮位置</label><div class="control-placement" role="group">${[['left','靠左'],['center','居中'],['right','靠右']].map(([value,label])=>`<button data-controls-position="${value}" class="${preferences.windowControls===value?'active':''}">${label}</button>`).join('')}</div><div class="wallpaper-actions"><button class="action-pill" data-pick-wallpaper>${svg('image')}选择背景图片</button>${windowNeedsRestart?'<button class="action-pill done" data-restart-app>应用并重启窗口</button>':''}</div></div><label class="background-slider">背景柔化 <output>${preferences.wallpaperBlur||0} px</output><input type="range" id="wallpaperBlur" min="0" max="40" value="${preferences.wallpaperBlur||0}"><small>调整自己的背景图片。</small></label><label class="background-slider">桌面底色浓度 <output>${preferences.backgroundTint||0}%</output><input type="range" id="backgroundTint" min="0" max="90" value="${preferences.backgroundTint||0}"><small>0% 不加底色，数值越高越柔和。</small></label></div>`;$('#glassSettings').after(panel);$('#backgroundMode').onchange=e=>saveAppearance({backgroundMode:e.target.value});for(const[id,key]of [['wallpaperBlur','wallpaperBlur'],['backgroundTint','backgroundTint']]){const input=$('#'+id);input.oninput=e=>{preferences[key]=Number(e.target.value);e.target.parentElement.querySelector('output').textContent=e.target.value+(key==='wallpaperBlur'?' px':'%');applyPreferences()};input.onchange=()=>saveAppearance({[key]:Number(input.value)})}const cache=document.createElement('section');cache.className='panel cache-settings';cache.id='cacheSettings';cache.innerHTML='<div class="settings-panel-heading"><h3>离线资料与缓存</h3><button class="ghost-link" data-refresh-cache>刷新用量</button></div><div id="cacheUsage">正在统计本机缓存…</div>';panel.after(cache);refreshCachePanel()};
async function refreshCachePanel(){try{const data=await invoke('cacheStats');cachePanelData=data;if(!$('#cacheUsage'))return;$('#cacheUsage').innerHTML=`<div class="cache-total"><strong>${data.total?bytes(data.total):'0 B'}</strong><span>缓存占用 · 不包含你的原始素材</span><button class="action-pill danger-quiet" data-clear-cache="all">清理全部缓存</button></div><div class="cache-groups">${data.groups.map(group=>`<div class="cache-group"><div><b>${esc(group.name)}</b><small>${group.count} 个文件</small></div><div class="cache-size-bar"><i style="width:${data.total?Math.max(2,group.size/data.total*100):0}%"></i></div><span>${group.size?bytes(group.size):'0 B'}</span><button class="ghost-link" data-clear-cache="${group.key}" ${group.size?'':'disabled'}>清理</button></div>`).join('')}</div><div class="cache-policy"><span>自动清理临时浏览缓存</span>${select('cacheDays',[['7','超过 7 天'],['30','超过 30 天'],['90','超过 90 天']],String(preferences.cacheDays))}${select('cacheLimit',[['128','上限 128 MB'],['512','上限 512 MB'],['1024','上限 1 GB']],String(preferences.cacheLimitMB))}</div><p class="hint">自动清理保留资料库作品的封面和主动缓存的离线资料。手动清理也不会删除观看记录、观后感或原始文件。</p><details class="cached-entry-list"><summary>逐条查看已缓存资料（${data.entries.filter(e=>e.cached).length}）</summary>${data.entries.filter(e=>e.size).slice(0,200).map(entry=>`<div class="cached-entry"><span>${esc(entry.title)}</span><small>资料 ${entry.metadata?bytes(entry.metadata):'0 B'} · 封面 ${entry.cover?bytes(entry.cover):'0 B'}</small><button class="ghost-link" data-clear-entry-cache="${esc(entry.id)}">清除</button></div>`).join('')||'<p class="hint">暂时没有作品离线缓存。</p>'}</details>`;$('#cacheDays').onchange=e=>saveAppearance({cacheDays:Number(e.target.value)});$('#cacheLimit').onchange=e=>saveAppearance({cacheLimitMB:Number(e.target.value)})}catch(error){if($('#cacheUsage'))$('#cacheUsage').textContent='缓存统计失败：'+error.message}}

document.addEventListener('input',e=>{if(e.target.matches('.personal-review'))queuePersonalDraft()});
document.addEventListener('change',e=>{const input=e.target.closest('[data-select-entry]');if(input){if(input.checked)selection.add(input.dataset.selectEntry);else selection.delete(input.dataset.selectEntry);input.closest('[data-open]').classList.toggle('entry-selected',input.checked);updateBatchBar()}});
document.addEventListener('drop',async e=>{if(!$('#sheet .personal-space')||!current)return;e.preventDefault();e.stopImmediatePropagation();$('#dropZone').hidden=true;try{await attachPersonal(e.dataTransfer.files)}catch(error){toast(error.message)}},true);
document.addEventListener('click',async e=>{
  const target=e.target;
  if(target.closest('.entry-selection')){e.stopImmediatePropagation();return}
  const control=target.closest('[data-controls-position],[data-inline-density],[data-library-masonry],[data-select-mode],[data-select-all],[data-select-none],[data-delete-one],[data-delete-selected],[data-confirm-entry-delete],[data-undo-deletion],[data-cache-one],[data-cache-batch],[data-detail-pane],[data-rate],[data-personal-materials],[data-unlink-material],[data-personal-image],[data-open-source],[data-open-source-provider],[data-refresh-source],[data-pick-wallpaper],[data-restart-app],[data-refresh-cache],[data-clear-cache],[data-clear-entry-cache],[data-masonry-more],[data-database-retry]');if(!control)return;e.preventDefault();e.stopImmediatePropagation();try{
    if(control.hasAttribute('data-controls-position'))await saveAppearance({windowControls:control.dataset.controlsPosition});
    else if(control.hasAttribute('data-inline-density')){await saveAppearance({density:control.dataset.inlineDensity});if(state.tab==='library')renderLibrary();else if(state.tab==='catalog')renderCatalog()}
    else if(control.hasAttribute('data-library-masonry')){state.view=state.view==='masonry'?'grid':'masonry';localStorage.setItem('yingji-view',state.view);renderLibrary()}
    else if(control.hasAttribute('data-select-mode')){selectionMode=!selectionMode;if(!selectionMode)selection.clear();renderResults()}
    else if(control.hasAttribute('data-select-all')){filtered().forEach(i=>selection.add(i.id));renderResults()}
    else if(control.hasAttribute('data-select-none')){selection.clear();renderResults()}
    else if(control.hasAttribute('data-delete-one'))chooseDeletion([control.dataset.deleteOne]);
    else if(control.hasAttribute('data-delete-selected'))chooseDeletion([...selection]);
    else if(control.hasAttribute('data-confirm-entry-delete')){const result=await invoke('removeEntries',deleteIds);undoDeletion=result.undoToken;state.library=result;selection.clear();closeSheet();if(state.tab==='library')renderLibrary();updateNavigation();toast('条目已移除，原文件保留，可在工具栏撤销')}
    else if(control.hasAttribute('data-undo-deletion')){state.library=await invoke('restoreEntries',undoDeletion);undoDeletion=null;render();toast('条目已恢复')}
    else if(control.hasAttribute('data-cache-one'))await cacheBatch([control.dataset.cacheOne]);
    else if(control.hasAttribute('data-cache-batch'))await cacheBatch(selection.size?[...selection]:filtered().map(i=>i.id));
    else if(control.hasAttribute('data-detail-pane')){await flushPersonalDrafts();detailPane=control.dataset.detailPane;renderCatalogDetail()}
    else if(control.hasAttribute('data-rate')){const score=Number(control.dataset.rate),root=control.closest('.star-rating');root.querySelector('input').value=score;root.querySelectorAll('[data-rate]').forEach(b=>{b.classList.toggle('filled',Number(b.dataset.rate)>0&&Number(b.dataset.rate)<=score);b.setAttribute('aria-pressed',String(Number(b.dataset.rate)===score))});if(control.dataset.ratingTarget!=='episodeStars'){if($('#workReview'))queuePersonalDraft();else await persistWatch(current.id,{personalScore:score},false)}}
    else if(control.hasAttribute('data-personal-materials'))await attachPersonal();
    else if(control.hasAttribute('data-unlink-material')){const item=state.library.items.find(i=>i.id===current.id);state.library=await invoke('upsertEntry',{...item,materialIds:(item.materialIds||[]).filter(id=>id!==control.dataset.unlinkMaterial)});renderCatalogDetail()}
    else if(control.hasAttribute('data-personal-image')){const box=document.createElement('div');box.className='image-lightbox';box.innerHTML=`<img src="yingji-media://item/${esc(control.dataset.personalImage)}" alt="关联图片"><button aria-label="关闭图片">${svg('close')}</button>`;box.onclick=()=>box.remove();document.body.append(box)}
    else if(control.hasAttribute('data-open-source'))await invoke('openSource',{id:control.dataset.openSource});
    else if(control.hasAttribute('data-open-source-provider'))await invoke('openSource',{provider:catalogClient.provider,kind:catalogClient.kind,sort:catalogClient.sort,year:catalogClient.year,quarter:catalogClient.quarter,region:catalogClient.region,format:catalogClient.format});
    else if(control.hasAttribute('data-refresh-source')){await flushPersonalDrafts();const id=control.dataset.refreshSource;const data=await invoke('refreshWork',id);state.library=await invoke('load');catalogClient.details.set(id,data);catalogDetailState={...data,id};thumbnailCache.delete(id);renderCatalogDetail();toast('源站资料已刷新，个人记录保留')}
    else if(control.hasAttribute('data-pick-wallpaper')){const info=await invoke('pickWallpaper');if(info){wallpaperAvailable=true;wallpaperStamp='?v='+Date.now();await saveAppearance({backgroundMode:'wallpaper'})}}
    else if(control.hasAttribute('data-restart-app'))await invoke('restart');
    else if(control.hasAttribute('data-refresh-cache'))await refreshCachePanel();
    else if(control.hasAttribute('data-clear-cache')||control.hasAttribute('data-clear-entry-cache')){await invoke('clearCache',control.hasAttribute('data-clear-entry-cache')?{id:control.dataset.clearEntryCache}:{group:control.dataset.clearCache});thumbnailCache.clear();catalogClient.details.clear();await refreshCachePanel();toast('缓存已清理，个人记录与原文件保留')}
    else if(control.hasAttribute('data-masonry-more'))await loadMoreMasonry();
    else if(control.hasAttribute('data-database-retry'))await openDatabase(current);
  }catch(error){toast(error.message)}
},true);
if(window.yingji)window.yingji.onProgress(progress=>{if(progress.kind==='database'&&current?.id===progress.itemId)document.querySelectorAll('.database-progress').forEach(box=>{box.querySelector('i').style.width=progress.percent+'%';box.querySelector('span').textContent=progress.phase});if(progress.kind==='cache')setTaskStatus(`正在缓存资料 · ${progress.count} / ${progress.total}`,true);if(progress.kind==='cache-done'){setTaskStatus(progress.failed?'缓存完成 · '+progress.failed+' 项待重试':'作品资料已缓存');if(state.tab==='settings')refreshCachePanel();invoke('load').then(library=>{state.library=library;updateNavigation();if(state.tab==='library'&&$('#overlay').hidden)renderResults()}).catch(()=>{})}});
window.YingjiFeatures={selection,flush:flushPersonalDrafts,version:'0.4.4'};
if(state.tab==='catalog')renderCatalog();else render();

let closeIconsFrame=0;new MutationObserver(()=>{if(closeIconsFrame)return;closeIconsFrame=requestAnimationFrame(()=>{closeIconsFrame=0;document.querySelectorAll('.sheet-close:not(:has(svg))').forEach(button=>button.innerHTML=svg('close'))})}).observe(document.querySelector('#sheet'),{childList:true,subtree:true});

let materialLayoutFrame=0;function scheduleMaterialLayout(){if(materialLayoutFrame)return;materialLayoutFrame=requestAnimationFrame(()=>{materialLayoutFrame=0;const grid=document.querySelector('.materials-masonry');if(!grid)return;if(window.YingjiRefinements){YingjiRefinements.layoutMaterialWall();return}if([...grid.querySelectorAll('video')].some(v=>!v.paused))return;const figures=[...grid.querySelectorAll('.material-tile')];figures.forEach((f,i)=>{if(!f.dataset.order)f.dataset.order=String(i+1)});figures.sort((a,b)=>Number(a.dataset.order)-Number(b.dataset.order));const count=Math.max(1,Math.min(3,figures.length,Math.floor(grid.clientWidth/220))),width=(grid.clientWidth-(count-1)*15)/count,heights=Array(count).fill(0),assignments=figures.map(figure=>{const media=figure.querySelector('img,video'),ratio=Number(media?.style.aspectRatio)||1.2,index=heights.indexOf(Math.min(...heights));heights[index]+=width/ratio+40;return index}),current=[...grid.children].filter(e=>e.classList.contains('material-column'));grid.style.setProperty('--material-cols',count);if(current.length===count&&figures.every((figure,index)=>figure.parentElement===current[assignments[index]]))return;const columns=Array.from({length:count},()=>{const column=document.createElement('div');column.className='material-column';return column});figures.forEach((figure,index)=>columns[assignments[index]].append(figure));grid.replaceChildren(...columns)})}
let materialWidth=0;new ResizeObserver(()=>{const grid=document.querySelector('.materials-masonry');if(grid&&Math.abs(grid.clientWidth-materialWidth)>1){materialWidth=grid.clientWidth;scheduleMaterialLayout()}}).observe(document.querySelector('#sheet'));

const videoPosterQueue=[];let videoPosterRunning=0,videoPosterObserver=null,videoPosterRoot=null;function observeVideoPoster(media){const root=document.querySelector('#detailScroll');if(videoPosterRoot!==root){videoPosterObserver?.disconnect();videoPosterRoot=root;videoPosterObserver=new IntersectionObserver(entries=>{for(const entry of entries)if(entry.isIntersecting){videoPosterObserver.unobserve(entry.target);videoPosterQueue.push(entry.target)}pumpVideoPosters()},{root,rootMargin:'180px'})}videoPosterObserver.observe(media)}
function pumpVideoPosters(){while(videoPosterRunning<2&&videoPosterQueue.length){const media=videoPosterQueue.shift();if(!media.isConnected)continue;videoPosterRunning++;(async()=>{try{const id=media.closest('[data-material-id]').dataset.materialId,url=await invoke('thumbnail',id);if(url&&media.isConnected){media.poster=url;const picture=new Image();picture.onload=()=>{if(media.isConnected&&picture.naturalWidth&&picture.naturalHeight){media.style.aspectRatio=String(picture.naturalWidth/picture.naturalHeight);scheduleMaterialLayout()}};picture.src=url}}catch{}finally{videoPosterRunning--;pumpVideoPosters()}})()}}
